var MODE = %s;
var TOT  = %s;   // COMPLETE designs — total pieces
var COLS = %s;   // COMPLETE designs — colours; one complete set is COLS x 4 sizes
var PCS  = %s;   // SETS designs — pieces per colour
function isC(no){ return MODE[no] === 'C'; }
function unit(no){ return isC(no) ? COLS[no] * 4 : 4; }
function totOf(no,c){ return isC(no) ? TOT[no] : PCS[no][c]; }
function arD(n){ return String(n).replace(/\d/g, function(d){ return '٠١٢٣٤٥٦٧٨٩'[+d]; }); }
function arSets(n){ return n===1 ? 'طقم واحد' : n===2 ? 'طقمان' : arD(n)+' أطقم'; }
function arPcs(n){ return n===1 ? 'قطعة واحدة' : n===2 ? 'قطعتان' : arD(n)+(n<=10?' قطع':' قطعة'); }
function arDesigns(n){ return n===1 ? 'تصميم واحد' : n===2 ? 'تصميمان' : arD(n)+' تصاميم'; }
function arColours(n){ return n===1 ? 'لون واحد' : n===2 ? 'لونان' : arD(n)+(n<=10?' ألوان':' لونًا'); }
function arFull(n){ return n===1 ? 'طقم كامل' : n===2 ? 'طقمان كاملان' : arD(n)+' أطقم كاملة'; }
function pcsOf(no,c,v){ return v==='F' ? totOf(no,c) : v*unit(no); }
function setsOf(no,c,v){ return v==='F' ? Math.floor(totOf(no,c)/unit(no)) : v; }
function labEn(no,c,v){
  var C = isC(no), u = unit(no), p = totOf(no,c);
  if (v!=='F') return C ? (v + (v===1?' complete set':' complete sets')) : (v + (v===1?' set':' sets'));
  var st = Math.floor(p/u), r = p%%u;
  var rl = r + (r===1 ? ' pc' : ' pcs');
  if (!st) return rl;
  return (C ? st+(st===1?' complete set':' complete sets') : st+(st===1?' set':' sets')) + ' + ' + rl;
}
function labAr(no,c,v){
  var C = isC(no), u = unit(no), p = totOf(no,c);
  if (v!=='F') return C ? arFull(v) : arSets(v);
  var st = Math.floor(p/u), r = p%%u;
  if (!st) return arPcs(r);
  return (C ? arFull(st) : arSets(st)) + ' + ' + arPcs(r);
}

