function segs(d, cset, cols, pcs){
  var A = '، ';   // Arabic comma: '·' is indistinguishable from the Arabic zero '٠'
  var en = '<b>' + d + (d===1?' design':' designs') + '</b>';
  var ar = arDesigns(d);
  if (cset){ en += ' · ' + cset + (cset===1?' complete set':' complete sets'); ar += A + arFull(cset); }
  if (cols){ en += ' · ' + cols + (cols===1?' colour':' colours');             ar += A + arColours(cols); }
  en += ' · <b>' + pcs + ' pcs</b>'; ar += A + arPcs(pcs);
  return [en, ar];
}
function refresh(){
  var cset = 0, cols = 0, pcs = 0, designs = {}, any = 0;
  for (var k in state){ var p = k.split(':'); designs[p[0]] = 1; any++;
    pcs += pcsOf(p[0], +p[1], state[k]);
    if (isC(p[0])) cset += setsOf(p[0], +p[1], state[k]); else cols++; }
  var d = Object.keys(designs).length;
  ok.disabled = !any;
  if (!any){ sum.innerHTML = 'Nothing selected yet<span class="ar">لم تختر شيئًا بعد</span>'; return; }
  var s = segs(d, cset, cols, pcs);
  sum.innerHTML = s[0] + '<span class="ar">' + s[1] + '</span>';
}

