function markPhoto(photoEl, chosen){        // chosen: {colourNo: sets}; COMPLETE uses key 0
  var img = photoEl.querySelector('img'), t = photoEl.closest('.design').dataset.no;
  var W = img.naturalWidth, H = img.naturalHeight, c = document.createElement('canvas'); c.width = W; c.height = H;
  var g = c.getContext('2d'); g.drawImage(img, 0, 0);
  if (isC(t)){
    tag(g, W / 2, H, W * 0.9, labEn(t, 0, chosen[0]), labAr(t, 0, chosen[0]), W);   // every colour is in, nothing fades
  } else {
    var n = +photoEl.dataset.n;
    var nums = photoEl.dataset.nums.split(',').map(Number);
    var cols = photoEl.dataset.cols ? photoEl.dataset.cols.split(';').map(function(p){ return p.split(',').map(Number); })
             : nums.map(function(_, i){ return [i / n, (i + 1) / n]; });
    for (var i = 0; i < n; i++){
      var no = nums[i], sets = no ? chosen[no] : 0;
      var x0 = cols[i][0] * W, x1 = cols[i][1] * W, cw = x1 - x0;
      if (!sets){ g.fillStyle = 'rgba(236,233,226,0.72)'; g.fillRect(x0, 0, cw + 1, H); continue; }
      tag(g, x0 + cw / 2, H, cw, no + '  \u00B7  ' + labEn(t, no, sets), labAr(t, no, sets), W);
    }
  }
  stamp(g, t, H);
  var out = document.createElement('img'); out.src = c.toDataURL('image/jpeg', 0.85); out.alt = 'Design ' + t + ' with chosen colours marked';
  c.toBlob(function(b){ if (b) shareFiles.push(new File([b], 'SJ-' + t + '-order.jpg', {type: 'image/jpeg'})); }, 'image/jpeg', 0.85);
  return out;
}

