ok.addEventListener('click', function(){
  var byDesign = {}, cset = 0, cols = 0, pcs = 0;
  Object.keys(state).sort().forEach(function(k){
    var p = k.split(':'); (byDesign[p[0]] = byDesign[p[0]] || {})[+p[1]] = state[k];
    pcs += pcsOf(p[0], +p[1], state[k]);
    if (isC(p[0])) cset += setsOf(p[0], +p[1], state[k]); else cols++;
  });
  var d = new Date(), date = d.getDate() + ' ' + ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][d.getMonth()] + ' ' + d.getFullYear();
  var lines = ['Order request · طلب شراء', date, ''];
  var ORD = [], ord = [];
  Object.keys(byDesign).forEach(function(no){ ord.push(no); });
  ord.sort(function(a,b){ return PAGE_ORDER.indexOf(a) - PAGE_ORDER.indexOf(b); });
  ord.forEach(function(no){
    if (isC(no)){
      var v = byDesign[no][0];
      ORD.push({ no: no, rows: [{ c: 0, en: labEn(no, 0, v), ar: labAr(no, 0, v) }] });
      lines.push(no + ' — ' + labEn(no, 0, v) + ' / ' + labAr(no, 0, v));
    } else {
      var cs = Object.keys(byDesign[no]).map(Number).sort(function(a,b){ return a - b; });
      ORD.push({ no: no, rows: cs.map(function(c){
        return { c: c, en: labEn(no, c, byDesign[no][c]), ar: labAr(no, c, byDesign[no][c]) }; }) });
      lines.push(no + ' — ' + cs.map(function(c){
        return 'colour ' + c + ' (' + labEn(no, c, byDesign[no][c]) + ' / ' + labAr(no, c, byDesign[no][c]) + ')';
      }).join(', '));
    }
  });
  var nd = ord.length, s = segs(nd, cset, cols, pcs);
  var tEn = s[0].replace(/<[^>]+>/g, ''), tAr = s[1];
  lines.push('', 'Total: ' + tEn + ' / ' + tAr);
  window.SJ_ORDER = { date: date, designs: ORD, tEn: tEn, tAr: tAr };
  var code = Object.keys(state).sort().map(function(k){ return k.replace(':', '-') + '-' + state[k]; }).join(',');
  lines.push('', 'Marked photos · الصور المعلّمة', 'https://abbas911-prog.github.io/sj-designs/' + PAGE_FILE + '#o=' + code);
  orderLines = lines;
  try { var v = localStorage.getItem('sj-notes'); if (v) document.getElementById('f-notes').value = v; } catch (e) {}
  var text = buildText();
  shareFiles = []; shareText = text;
  var marks = document.getElementById('marks'); marks.innerHTML = '';
  ord.forEach(function(no){
    document.querySelectorAll('.design[data-no="' + no + '"] .photo').forEach(function(ph){
      if (isC(no)){ marks.appendChild(markPhoto(ph, byDesign[no])); return; }
      var nums = ph.dataset.nums.split(',').map(Number), any = false;
      nums.forEach(function(x){ if (x && byDesign[no][x]) any = true; });
      if (any) marks.appendChild(markPhoto(ph, byDesign[no]));
    });
  });
  var sb = document.getElementById('share');
  var canShare = !!navigator.share;
  sb.hidden = !canShare; document.getElementById('wa').hidden = canShare;
  document.getElementById('done').hidden = false; document.getElementById('bar').hidden = true;
  document.getElementById('done').scrollTop = 0; window.scrollTo(0,0);
});

